package app.kinnect.audit;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.net.*;import java.io.*;import java.util.concurrent.atomic.*;import org.json.*;import org.webrtc.*;
/** Uses the unchanged production NativeRtc through a private test bridge, no app accounts. */
public final class NativeSfuAudit extends Instrumentation {
 java.util.concurrent.ExecutorService writer=java.util.concurrent.Executors.newSingleThreadExecutor();volatile boolean collecting=true;volatile Activity resumed;volatile Throwable failure;Socket socket;PrintWriter output;Object publisher,viewer;AtomicInteger frames=new AtomicInteger();
 public void onCreate(Bundle b){super.onCreate(b);start();}public void callActivityOnResume(Activity a){super.callActivityOnResume(a);resumed=a;}
 Object call(Object o,String n,Class[]types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(o,args);}Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void send(JSONObject m){final String value=m.toString();writer.execute(()->{output.println(value);});}
 Object events(ClassLoader cl,Class<?> type,String member){return java.lang.reflect.Proxy.newProxyInstance(cl,new Class[]{type},(p,m,args)->{if(m.getName().equals("signal")){JSONObject payload=(JSONObject)args[1];payload.put("type","signal");payload.put("member",member);payload.put("to",args[0]);send(payload);}return null;});}
 public void onStart(){Bundle result=new Bundle();Activity activity=null;try{
  ClassLoader cl=getTargetContext().getClassLoader();Class<?> api=cl.loadClass("app.kinnect.live.NativeApi");call(api.getField("shared").get(null),"configure",new Class[]{String.class},"https://127.0.0.1:9");new Handler(Looper.getMainLooper()).post(()->getTargetContext().startActivity(new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));for(int n=0;n<80&&resumed==null;n++)Thread.sleep(100);activity=resumed;if(activity==null)throw new AssertionError("Activity missing");final Activity a=activity;
  socket=new Socket("127.0.0.1",8791);socket.setSoTimeout(25000);output=new PrintWriter(new OutputStreamWriter(socket.getOutputStream(),"UTF-8"),true);BufferedReader input=new BufferedReader(new InputStreamReader(socket.getInputStream(),"UTF-8"));JSONObject config=new JSONObject(input.readLine());Class<?> rtc=cl.loadClass("app.kinnect.live.NativeRtc"),event=cl.loadClass("app.kinnect.live.NativeRtc$Events");Constructor<?> ctor=rtc.getDeclaredConstructor(Context.class,JSONObject.class,SurfaceViewRenderer.class,SurfaceViewRenderer.class,event,boolean.class);ctor.setAccessible(true);
  runOnMainSync(()->{try{LinearLayout root=new LinearLayout(a);root.setOrientation(1);SurfaceViewRenderer local=new SurfaceViewRenderer(a),remote=new SurfaceViewRenderer(a);root.addView(local,new LinearLayout.LayoutParams(-1,0,1));root.addView(remote,new LinearLayout.LayoutParams(-1,0,1));a.setContentView(root);publisher=ctor.newInstance(a,config,local,null,events(cl,event,"host"),false);viewer=ctor.newInstance(a,config,null,null,events(cl,event,"viewer"),false);call(viewer,"bindLive",new Class[]{String.class,SurfaceViewRenderer.class},"host",remote);remote.addFrameListener(new org.webrtc.EglRenderer.FrameListener(){public void onFrame(android.graphics.Bitmap bitmap){if(bitmap!=null)bitmap.recycle();frames.incrementAndGet();if(collecting)remote.addFrameListener(this,0f);}},0f);call(publisher,"media",new Class[]{Context.class,boolean.class},a,true);call(publisher,"microphone",new Class[]{boolean.class},false);}catch(Throwable e){failure=e;}});if(failure!=null)throw new AssertionError(failure);send(new JSONObject().put("type","ready"));
  java.util.concurrent.LinkedBlockingQueue<JSONObject> incoming=new java.util.concurrent.LinkedBlockingQueue<>();Thread reader=new Thread(()->{try{String line;while((line=input.readLine())!=null)incoming.put(new JSONObject(line));}catch(Exception ignored){}},"SfuAuditReader");reader.setDaemon(true);reader.start();long deadline=System.currentTimeMillis()+25000;while(frames.get()<5&&System.currentTimeMillis()<deadline){JSONObject m=incoming.poll(250,java.util.concurrent.TimeUnit.MILLISECONDS);if(m==null)continue;runOnMainSync(()->{try{if(m.optString("type").equals("publish"))call(publisher,"offer",new Class[]{String.class},"@sfu");else if(m.optString("type").equals("signal"))call(m.optString("to").equals("host")?publisher:viewer,"signal",new Class[]{String.class,JSONObject.class},m.optString("from"),m);else if(m.optString("type").equals("media-error"))failure=new AssertionError("SFU media error");}catch(Throwable e){failure=e;}});if(failure!=null)throw new AssertionError(failure);if(m.optJSONObject("description")!=null&&m.optJSONObject("description").optString("type").equals("answer")){for(int n=0;n<40&&frames.get()<5;n++)Thread.sleep(100);}}
  if(frames.get()<5)throw new AssertionError("No SFU decoded camera frames: "+frames.get());if(((java.util.Map)get(publisher,"peers")).size()!=1)throw new AssertionError("Publisher has more than one media connection");if(get(a,"socket")!=null)throw new AssertionError("Unexpected public room connection");result.putString("result","PASS: unchanged production APK NativeRtc camera -> SFU -> NativeRtc viewer decodes "+frames.get()+" frames, single uplink, no public room.");send(new JSONObject().put("type","done"));finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{collecting=false;final Activity a=activity;runOnMainSync(()->{try{if(publisher!=null)call(publisher,"close",new Class[]{});if(viewer!=null)call(viewer,"close",new Class[]{});}catch(Exception ignored){}if(a!=null)a.finish();});try{writer.shutdownNow();if(socket!=null)socket.close();}catch(Exception ignored){}}}
}
